package com.ranjith.arena.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="interview_sessions") public class InterviewSession {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String candidateName; private String role; private String interviewerVoice; private Long resumeId; private int durationMinutes=20; private String status="READY"; private int questionCount; private LocalDateTime startedAt,endedAt;
 public Long getId(){return id;} public String getCandidateName(){return candidateName;} public void setCandidateName(String v){candidateName=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getInterviewerVoice(){return interviewerVoice;} public void setInterviewerVoice(String v){interviewerVoice=v;} public Long getResumeId(){return resumeId;} public void setResumeId(Long v){resumeId=v;} public int getDurationMinutes(){return durationMinutes;} public void setDurationMinutes(int v){durationMinutes=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public int getQuestionCount(){return questionCount;} public void setQuestionCount(int v){questionCount=v;} public LocalDateTime getStartedAt(){return startedAt;} public void setStartedAt(LocalDateTime v){startedAt=v;} public LocalDateTime getEndedAt(){return endedAt;} public void setEndedAt(LocalDateTime v){endedAt=v;}
}
